using Json.JsonE;

namespace LearnJsonEverything;

public class Lesson : ILessonRunner<JsonNode?>
{
    public JsonNode? Run(JsonObject test)
    {
        var template = test["template"];
        var context = test["context"]!.AsObject();

        context["hasSymbol"] = JsonFunction.Create((parameters, ctx) =>
        {
            if (parameters.Length != 1) return false;
            if (parameters[0] is not JsonValue value) return false;
            if (!value.TryGetValue<string>(out var symbolName) || string.IsNullOrWhiteSpace(symbolName)) return false;

            return ctx.IsDefined(symbolName);
        });

        return JsonE.Evaluate(template, context);
    }
}

