using System.Text.Json.Nodes;
using Json.JsonE;

namespace LearnJsonEverything;

public class Lesson : ILessonRunner<JsonNode?>
{
    private static string Map(JsonEException error)
    {
        return error switch
        {
            TemplateException => "template",
            InterpreterException => "interpreter",
            BuiltInException => "builtin",
            SyntaxException => "syntax",
            _ => "unknown"
        };
    }

    public JsonNode? Run(JsonObject test)
    {
        try
        {
            return JsonE.Evaluate(test["template"], test["context"]);
        }
        catch (JsonEException error)
        {
            return Map(error);
        }
    }
}
